UPDATE bd_class
set course_name = #{courseName}
WHERE id = #{id}

mapper.select:
SELECT bishop_teacher_id, sum( exist_students ) taught_stu_num FROM bd_class cls WHERE bishop_teacher_id IN
#{id}
GROUP BY bishop_teacher_id;

SELECT GROUP_CONCAT( class_name ) bishop_classes, bishop_teacher_id id FROM bd_class WHERE bishop_teacher_id IN
#{id}
AND is_delete = 0 AND class_state = 0 GROUP BY bishop_teacher_id

SELECT class_name, id, sum_students, exist_students FROM bd_class WHERE id IN
#{id}
and is_delete = 0

SELECT cls.id, cou.color course_color , bis.`name` bishop_teacher_name, help_tea.name help_teacher_name, cls.exist_students, cls.sum_students FROM bd_class cls LEFT JOIN bd_course cou ON cou.id = cls.class_course_id LEFT JOIN bd_teacher bis ON cls.bishop_teacher_id = bis.id LEFT JOIN bd_teacher help_tea ON cls.help_teacher_id = help_tea.id WHERE cls.id IN
#{id}
and cls.is_delete = 0
